#!/usr/bin/env python3
"""Build one offline HTML file from actual screenshot capture manifest; no network dependencies."""
import argparse,base64,html,json
from pathlib import Path
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--input',type=Path,default=Path('docs/report/evidence/component-system'))
parser.add_argument('--output',type=Path,default=Path('docs/design-review.html'))
args=parser.parse_args();manifest=json.loads((args.input/'manifest.json').read_text())
records=manifest['records'];cards=[]
for record in records:
 image=args.input/record['file'];assert image.exists(),image
 src='data:image/png;base64,'+base64.b64encode(image.read_bytes()).decode()
 label=html.escape(record['label']);note=html.escape(record.get('note',''))
 cards.append(f'''<article data-theme="{html.escape(record['theme'])}" data-group="{html.escape(record['group'])}"><button class="screen" aria-label="{label} 열기"><img loading="lazy" width="1080" height="2400" src="{src}" alt="{label} Android 실제 화면"></button><h2>{label}</h2><p>{note or '기본 글자 크기 · Android XML'}</p></article>''')
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>때맞춤 · 디자인 화면 모음</title>
<style>
:root{color-scheme:light;--bg:#f5f5f7;--surface:#fff;--text:#1c1c1e;--muted:#66666d;--line:#dddde1}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body.dark{color-scheme:dark;--bg:#101012;--surface:#1c1c1f;--text:#f5f5f7;--muted:#acacb4;--line:#333337}header,main{max-width:1480px;margin:auto;padding:28px 32px}header{padding-bottom:12px}h1{font-size:28px;letter-spacing:-.025em;margin:0 0 8px}header p{margin:4px 0;color:var(--muted)}.meta{font-size:12px}.credits{max-width:1416px;margin:0 auto 24px;padding:16px 20px}.credits pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}nav{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;position:sticky;top:0;z-index:2;padding:14px 32px;background:var(--surface);border-bottom:1px solid var(--line)}.group{display:flex;flex-wrap:wrap;gap:6px}button{font:inherit;cursor:pointer;color:inherit;border:0}nav button{padding:10px 16px;border-radius:24px;background:var(--bg);min-height:44px}nav button[aria-pressed=true]{background:var(--text);color:var(--surface)}button:focus-visible{outline:3px solid #538ab4;outline-offset:4px}.contract{background:var(--surface);padding:16px 20px;border-radius:16px;margin-bottom:24px}.contract summary{cursor:pointer;min-height:28px;font-weight:600}.contract table{width:100%;border-collapse:collapse;font-size:13px}.contract th,.contract td{overflow-wrap:anywhere;text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:10px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:32px 24px;align-items:start}article[hidden]{display:none}article h2{font-size:16px;margin:12px 0 2px}article p{font-size:13px;color:var(--muted);margin:0}.screen{padding:0;display:block;width:100%;border-radius:14px;background:var(--surface);overflow:hidden;box-shadow:0 4px 18px #00000008}.screen img{display:block;width:100%;height:auto}dialog{padding:20px;background:var(--surface);color:var(--text);border:0;border-radius:18px;max-width:95vw;max-height:96vh}dialog::backdrop{background:#0009}dialog img{display:block;max-height:80vh;max-width:85vw;width:auto;height:auto;margin:auto}dialog button{display:block;margin:12px 0 0 auto;background:var(--bg);border-radius:22px;padding:10px 20px;min-height:44px}#count{margin:0 0 20px;color:var(--muted)}footer{padding:0 32px 32px;color:var(--muted);max-width:1480px;margin:auto;font-size:13px}@media(max-width:600px){header,main{padding:20px}nav{padding:12px 20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 12px}h1{font-size:24px}article h2{font-size:14px}nav button{padding:10px 12px}footer{padding:0 20px 24px}}@media print{nav,.screen+button,dialog{display:none}body{background:white}.grid{grid-template-columns:repeat(4,1fr)}article{break-inside:avoid}}
</style>
<header><h1>때맞춤 디자인 화면 모음</h1><p>화이트 · 중성 유리 바 · 실사 날씨. S1–S8과 하위 화면, 재사용 컴포넌트의 실제 Android 화면입니다.</p><p>이 HTML 파일 하나를 보내면 인터넷 없이 열 수 있습니다. 화면은 예시 데이터이며 실제 계정·저장·날씨·알림·가족 공유·OCR 연동은 포함하지 않습니다.</p><p>Android 캡처 이미지 모음입니다. 이미지를 누르면 확대되며 화면 안의 버튼은 동작하지 않습니다. 공통 상태·날씨 이미지는 라이트 기준으로 두 테마 필터에 함께 표시합니다.</p><p class="meta">APP_COMMIT · fontScale 1.0 · 이미지 TOTAL개</p></header>
<nav aria-label="화면 필터"><div class="group" aria-label="테마"><button data-theme-filter="light" aria-pressed="true">라이트</button><button data-theme-filter="dark" aria-pressed="false">다크</button></div><div class="group" aria-label="범위"><button data-group-filter="all" aria-pressed="true">전체</button><button data-group-filter="screens" aria-pressed="false">전체 화면</button><button data-group-filter="components" aria-pressed="false">컴포넌트</button><button data-group-filter="states" aria-pressed="false">상태·날씨</button></div></nav>
<main><details class="contract"><summary>팀원 적용 · 공통 토큰과 컴포넌트 계약</summary><p>새 화면도 같은 색·글자·간격을 사용합니다. 컴포넌트는 외부 상태를 표시하고 이벤트만 전달하며 실제 저장·날씨 판단을 하지 않습니다.</p><table><tr><th>역할</th><th>유지할 규격</th></tr><tr><td>색</td><td>화이트/중성 다크 · 주요 버튼만 브랜드색 · 임박 주황 · 오늘/지남 빨강</td></tr><tr><td>글자</td><td>Pretendard · 화면 제목34 · 섹션22 · 본문/주요 버튼17 · 라벨15 · 작은 버튼14 · 설명13 · 탭12sp</td></tr><tr><td>공통 배치</td><td>좌우20dp · 간격4/8/12/16/20/24/32dp · 터치48dp 이상 · 버튼14dp 모서리·테두리 없음</td></tr><tr><td>WeatherProposalView</td><td>상태/제목/이유/버튼 라벨/busy 입력 → 변경·유지·상세 콜백. 판단 불가에는 변경 버튼 없음</td></tr><tr><td>OptionalItemFieldsView</td><td>제품명/장소/메모/펼침 입력 → 필드별 변경·펼침 콜백. 초안은 화면이 보존</td></tr><tr><td>CyclePresetView</td><td>라벨 배열 → 선택 index 콜백. 예시값이며 실제 권장 주기는 설명서 확인</td></tr><tr><td>CompletionDateView</td><td>날짜 표시/활성 상태 → 날짜 변경 콜백. 범위·Picker·저장은 화면이 담당</td></tr><tr><td>SheetShadowView</td><td>모달 위쪽 둥근 모서리 바깥의 그림자. 같은 부모·X/폭, 48dp 높이로 패널 앞에 배치하고 follow(sheet) 연결. 패널 이동·숨김을 따라가며 핸들 아래에는 그림자를 넣지 않음</td></tr><tr><td>목록 빠른 완료</td><td>행은 상세로, 별도 체크는 오늘 완료. 미리보기에서 10초 되돌리기 제공</td></tr></table><p>코드: ui/component · res/layout/component_* · res/values/themes.xml. 전체 계약과 실제 연결 경계는 저장소 docs/DESIGN_SYSTEM.md에 있습니다.</p></details><p id="count" aria-live="polite"></p><div class="grid">CARDS</div></main>
<footer>캡처마다 원래의 폰트 크기를 유지했습니다. ‘아래 영역’은 같은 화면을 스크롤한 장면입니다. 카메라·사진 OCR은 별도 무료 실험 계획입니다. 사진·Pretendard 라이선스와 코드의 재사용 규격은 저장소 디자인 시스템을 참고하세요.</footer>
<dialog aria-label="화면 보기"><img alt=""><form method="dialog"><button>닫기</button></form></dialog>
<script>
let theme='light',group='all';const articles=[...document.querySelectorAll('article')],dialog=document.querySelector('dialog');
function filter(){let count=0;articles.forEach(a=>{a.hidden=!(a.dataset.theme===theme||a.dataset.theme==='common')||!(group==='all'||a.dataset.group===group);if(!a.hidden)count++});document.querySelector('#count').textContent=count+'개 화면 · '+(theme==='light'?'라이트':'다크');document.body.classList.toggle('dark',theme==='dark')}
document.querySelectorAll('[data-theme-filter]').forEach(b=>b.onclick=()=>{theme=b.dataset.themeFilter;document.querySelectorAll('[data-theme-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));filter()});
document.querySelectorAll('[data-group-filter]').forEach(b=>b.onclick=()=>{group=b.dataset.groupFilter;document.querySelectorAll('[data-group-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));filter()});
document.querySelectorAll('.screen').forEach(b=>b.onclick=()=>{const original=b.querySelector('img'),image=dialog.querySelector('img');image.src=original.src;image.alt=original.alt;dialog.showModal()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});filter();
</script></html>'''
page=page.replace('<footer>', '<details class=\"credits\"><summary>사진·글꼴 출처</summary><pre>'+html.escape(Path('app/src/main/assets/licenses/weather-photographs.txt').read_text())+'</pre><p>Pretendard · SIL Open Font License 1.1 · 화면에 사용된 글꼴은 APK에 포함됩니다.</p></details><footer>')
page=page.replace('APP_COMMIT',html.escape(manifest['app_commit'])).replace('TOTAL',str(len(records))).replace('CARDS',''.join(cards))
args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(page)
print(f'{args.output}: {len(records)} embedded screenshots, {args.output.stat().st_size:,} bytes')
